proof.raw_tex:
\begin{Lemma}\label{lemma descent}
Given $f:\R^n\rightarrow\R$ and $x,y\in\Omega$, assume that $f$ is differentiable on the line segment $[x,y]$ and its derivative is Lipschitz continuous on this segment with constant $L>0$. Then we have
\begin{align}\label{eq descent}
\abs{f(y)-f(x)-\dotproduct{\nabla f(x),y-x}}\le \frac{L}{2}\norm{y-x}^2.
\end{align}
\end{Lemma}

\begin{Lemma}\label{isolation lemma}
Let $f:\R^n\rightarrow\overline{\R}$ be continuous around some local minimizer $\bar x$ and satisfy the PLK condition at $\bar x$. Then there is a neighborhood $U$ of $\bar x$ such that $f(\bar x)$ is the unique critical value of $f$ in $U$.
\end{Lemma}

\begin{proof}
The PLK condition for $f$ at $\bar x$ gives us $\eta\in(0,\infty],$ a neighborhood $U$ of $\bar x$, and a function $\varphi:[0,\eta)\rightarrow[0,\infty)$ satisfying all the conditions in Definition~\ref{KL ine}. Since $f$ is continuous around the local minimizer $\bar x,$ we assume, by shrinking $U$ if necessary, that $f(\bar x)\le f(x)<f(\bar x)+\eta.$ Then condition (iv) in Definition~\ref{KL 2} can be rewritten as
\begin{align*}
\varphi'(f(x)-f(\bar x))d(0,\partial f(x))\ge 1\text{ whenever }x\in U,\;f(x)\ne f(\bar x).
\end{align*}
Therefore, $0\notin \partial f(x)$ for all such $x$, i.e., $f(\bar x)$ is the unique critical value of $f$ on $U.$ 
\end{proof}

\begin{Proposition}\label{general convergence under KL}
Let $f:\R^n\rightarrow\R$ be a $\mathcal{C}^1$-smooth function, and let the following conditions hold along a sequence of iterates $\set{x^k}\subset\R^n$ for the function $f$:
\begin{itemize}
\item[\bf(H1)] {\rm(primary descent condition)}. There exists $\sigma>0$ such that for sufficiently large $k\in\N$, we have 
\begin{align*}
 f(x^k)-f(x^{k+1})\ge\sigma\norm{\nabla f(x^k)}\cdot\norm{x^{k+1}-x^k}.
\end{align*}
\item[\bf(H2)] {\rm(complementary descent condition)}. For sufficiently large $k\in\N$, we have
\begin{align*}
 \big[f(x^{k+1})=f(x^k)\big]\Longrightarrow [x^{k+1}=x^k].
\end{align*}
\end{itemize}
If $\bar x$ is an accumulation point of $\set{x^k}$  and $f$ satisfies the PLK property at $\bar x$, then $x^k\rightarrow\bar x$ as $k\to\infty$.
\end{Proposition}

\begin{Proposition}\label{general rate}
Let $f:\R^n\rightarrow\R$ be a $\mathcal{C}^1$-smooth function, and let $\set{x^k}$ satisfy the conditions 
\begin{align}\label{two conditions}
f(x^k)-f(x^{k+1})\ge \alpha\norm{x^{k+1}-x^k}^2\;\text{ and }\;\norm{\nabla f(x^k)}\le \beta\norm{x^{k+1}-x^k}
\end{align}
for all $k\in\N$ sufficiently large with some constants $\alpha,\beta>0$. Suppose  in addition that $\bar x$ is an accumulation point of $\set{x^k}$ and that $f$ satisfies the $($exponential$)$ PLK property at $\bar x$ with $\varphi(t)=Mt^{1-q}$ for some $M>0$ and $q\in(0,1)$. Then the following convergence rates are guaranteed:

{\bf (i)} For $q\in(0,1/2)$, the sequence $\set{x^k}$ terminates at $\bar x$ in finite steps.

{\bf (ii)} For $q=1/2$, the sequence $\set{x^k}$ converges linearly to $\bar x$ as $k\to\infty$.

{\bf (iii)} For $q\in(1/2,1)$, we have  $\norm{x^k-\bar x}=\mathcal{O}( k^{-\frac{1-q}{2q-1}})$ as $k\to\infty$
\end{Proposition}

\begin{Proposition}\label{isolated} Let $f:\R^n\rightarrow\overline\R$ be a ${\cal C}^1$-smooth function around its local minimizer $\bar x$. Assume that $f$ satisfies the PLK condition at $\bar x$ with the desingularizing function $\psi:[0,\eta)\rightarrow[0,\infty)$ for some $\eta\in (0,\infty]$. Then the following assertions hold whenever $\varepsilon\in (0,1/4]$:

{\bf(i)} The collection of functions $\set{H_\alpha}_{\alpha\ge \varepsilon}$ satisfies the same PLK condition at $\bar z:=(\bar x,\bar x)$ with the desingularizing function $\varphi:[0,\eta)\rightarrow[0,\infty)$ defined by $\varphi(0):=0$ and 
\begin{align}\label{construction varphi}
\varphi(t):=\sqrt{\frac{8}{\varepsilon}}\int_0^{t/2} \max\set{\psi'(s),\frac{1}{\sqrt{s}}}ds\;\text{ for all }\;t\in (0,\eta).
\end{align}

{\bf(ii)} If $\psi(t)=Mt^{1-q}$ for some $M>0$ and $q\in[0,1)$, then the function $\varphi$ in \eqref{construction varphi} is given by $\varphi(t)=\frac{2^{\theta+1/2}\tilde M}{\sqrt{\varepsilon}(1-\theta)}t^{1-\theta}$ when $t\in (0,\delta)$ for some $\delta\in(0,\eta)$, where $\theta:=\max\set{q,\frac{1}{2}}$ and $\tilde{M}>0$ is defined as 
\begin{align}\label{tilde M}
\tilde{M}:=\begin{cases}
1&\text{ if }\quad q\in \left[0,\frac{1}{2}\right),\\
\max \set{M(1-q),1}&\text{ if }\quad q=\frac{1}{2},\\
M(1-q)&\text{ if }\quad q\in \left(\frac{1}{2},1\right).
\end{cases}
\end{align}
\end{Proposition}

\begin{proof}
To verify (i) pick any $\varepsilon \in (0,1/4]$ and use the PLK property of $f$ at its local minimizer $\bar x$ to find a neighborhood $U$ of $\bar x$ on which $f$ satisfies all the conditions in Definition~\ref{KL ine} with the corresponding desingularizing function $\psi: [0,\eta) \rightarrow [0,\infty)$. In particular, we have
\begin{align}\label{desingularizing}
\psi'\big(f(x)-f(\bar{x})\big)\norm{\nabla f(x)}\ge 1\;\mbox{  for all }\;x \in U\;\mbox{ with }\;f(\bar{x}) < f(x) < f(\bar{x}) + \eta.
\end{align}
The function $\varphi$ in \eqref{construction varphi} can be written as $\varphi(t)=\sqrt{\frac{8}{\varepsilon}}\phi\brac{\frac{t}{2}}$, where $\phi:[0,\eta)\rightarrow[0,\infty)$ is defined by 
\begin{align}\label{construction phi t}
\phi(t):=\int_0^t \max\set{\psi'(s),\frac{1}{\sqrt{s}}}ds\;\text{ for }\;t\in(0,\eta)\;\mbox{ with }\;\phi(0):=0.
\end{align}
It follows from the continuity of $\psi$ at $0$ that
\begin{align*}
0\le \phi(t)\le \int_0^t \psi'(s)ds+ \int_0^t\frac{1}{\sqrt{s}}ds=\psi(t)+2\sqrt{t}\;\text{ for }\;t\in(0,\eta).
\end{align*}
Passing the limit above as $t\rightarrow0^+$ and using the continuity of $\psi$ reveal that $\phi$ is also continuous at $0$. Moreover, we deduce from \eqref{construction phi t} that the derivative $\phi'(t)=\max \set{\psi'(t),\frac{1}{\sqrt{t}}}>0$ is positive, continuous, and nonincreasing on $(0,\eta)$, which ensures the concavity of $\phi$ on this interval. In addition, it follows that 
\begin{align}\label{phi'>1}
\phi'(f(x)-f(\bar x))\norm{\nabla f(x)}\ge \psi'(f(x)-f(\bar x))\norm{\nabla f(x)}\ge 1
\end{align}
for $x\in U$ with $f(\bar x)< f(x)<f(x)+\eta$. Since $\varphi(t)=\sqrt{\frac{8}{\varepsilon}}\phi\brac{\frac{t}{2}}$, the domain of $\varphi$ is $[0,2\eta).$ It is clear that $\varphi$ satisfies all the conditions as a desingularizing function on $[0,2\eta)$ with
\begin{align}\label{deri varphi}
\varphi'(t)=\sqrt{\frac{2}{\varepsilon}}\phi'\brac{\frac{t}{2}}>0 \text{ for all }t\in (0,2\eta).
\end{align}
Taking any $\alpha\ge \varepsilon$ and $z=(x,y)\in Z:= U\times U$ with 
\begin{align}\label{halpha}
H_\alpha(\bar z)<H_\alpha(z)<H_\alpha(\bar z)+\eta,
\end{align}
we aim at verifying the inequality
\begin{align}\label{KL R2n}
\varphi'(H_\alpha(z)-H_\alpha(\bar z))\norm{\nabla H_\alpha (z)}\ge 1.
\end{align}
To proceed, observe first the estimates
\begin{subequations}
\begin{align}
\norm{\nabla H_\alpha(x,y)}&=\sqrt{\norm{\nabla f(x)+2\alpha(x-y)}^2+\norm{2\alpha(x-y)}^2} \label{g_Hal.a}\\
&\ge \sqrt{\frac{1}{4}\norm{\nabla f(x)}^2+\alpha^2\norm{x-y}^2}\label{g_Hal.b}\\
&\ge \sqrt{\frac{1}{4}\norm{\nabla f(x)}^2+\alpha\varepsilon\norm{x-y}^2}\label{g_Hal.c}\\
&\ge \sqrt{\frac{\varepsilon}{2}}\brac{\norm{\nabla f(x)}+\sqrt{\alpha}\norm{x-y}},\label{g_Hal.d}
\end{align}
\end{subequations}
where \eqref{g_Hal.a} is comes from the construction of $H_\alpha$, \eqref{g_Hal.b} follows from the inequality $\norm{a+b}^2\ge \frac{1}{4}\norm{a}^2-\frac{3}{4}\norm{b}^2$ for $a,b\in\R^n$, \eqref{g_Hal.c} follows from $\alpha\ge \varepsilon$, and \eqref{g_Hal.d} follows from $a^2+b^2\ge \frac{1}{2}(a+b)^2$ for $a,b\in\R$ and $\varepsilon\le 1/4$.  Now let $S:=\max \set{\alpha\norm{x-y}^2,f(x)-f(\bar x)}$ and deduce from $f(x)\ge f(\bar x)$ as $x\in U$ that
\begin{align*}
H_\alpha(z)-H_\alpha(\bar z)=f(x)+\alpha\norm{x-y}^2-f(\bar x) \in [S,2S].
\end{align*}
Combining the latter with $0< H_\alpha(z)-H_\alpha(\bar z)<\eta$ by \eqref{halpha} gives us $S\in (0,\eta).$ Using the nonincreasing property of $\varphi'$ and the relation $\varphi'(t)=\sqrt{\frac{2}{\varepsilon}}\phi'\brac{\frac{t}{2}}$ from \eqref{deri varphi} yields
\begin{align*}
\varphi'(H_\alpha(z)-H_\alpha(\bar z))&\ge \varphi'\brac{2S}=\sqrt{\frac{2}{\varepsilon}}\phi'(S).
\end{align*}
Furthermore, it follows from  \eqref{deri varphi} and  \eqref{g_Hal.d} that
\begin{align*}
\varphi'(H_\alpha(z)-H_\alpha(\bar z))\norm{\nabla H_\alpha(x,y)}&\ge \sqrt{\frac{2}{\varepsilon}}\phi'(S)\sqrt{\frac{\varepsilon}{2}}\brac{\norm{\nabla f(x)}+\sqrt{\alpha}\norm{x-y}}\\
&=\phi'(S)\norm{\nabla f(x)}+\phi'(S)\sqrt{\alpha}\norm{x-y}.
\end{align*}
By $\phi'\big(f(x)-f(\bar{x})\big)\norm{\nabla f(x)}\ge 1$ coming from \eqref{phi'>1} and $\phi'(\alpha \norm{x-y}^2)\ge \frac{1}{\sqrt{\alpha}\norm{x-y}}$ due to $\phi'(t)\ge \frac{1}{\sqrt{t}}$ for $t\in (0,\eta),$ we get the estimate
\begin{align*}
\phi'(S)\norm{\nabla f(x)}+\phi'(S)\sqrt{\alpha}\norm{x-y}\ge 1,
\end{align*}
which therefore verifies assertion (i) of the proposition.

To prove assertion (ii)  is easier. Indeed, let $\psi(t)=Mt^{1-q}$ for $q\in[0,1)$, let $\theta:=\max\set{\frac{1}{2},q}\in (0,1)$, and take $\tilde M$ from \eqref{tilde M}. It readily follows that
\begin{align}\label{formu phi}
\max\set{\psi'(s),\frac{1}{\sqrt{s}}}=\tilde Ms^{-\theta}\text{ for all }s\in(0,\delta)
\end{align}
for some $\delta\in(0,\eta)$ sufficiently small.
Combining the latter with \eqref{construction phi t}, we arrive at 
\begin{align*}
 \varphi(t)=\sqrt{\frac{8}{\varepsilon}}\int_0^{t/2}\tilde{M}s^{-\theta}ds=\frac{2^{\theta+1/2}\tilde M}{\sqrt{\varepsilon}(1-\theta)}t^{1-\theta} \text{ for all }t\in (0,\delta),
\end{align*}
which thus verifies (ii) and completes the proof of the proposition.
\end{proof}

\begin{Proposition}\label{convergence rate deduce}
Let $f:\Omega\rightarrow{\R}$ be a function defined on open and convex set of $\Omega\subset\R^n$, and let $\bar x \in\Omega$. Assume that $f$ has a Lipschitz continuous gradient on $\Omega$ and take a sequence $\set{x^k}\subset\Omega $ converging to $\bar x$. Suppose in addition that there exists $\alpha>0$ such that 
\begin{align}\label{main condition rate}
\alpha\norm{\nabla f(x^k)}^2\le f(x^k)-f(x^{k+1})\;\text{ for all large }\;k\in\N.
\end{align}
Then the linear convergence of $x^k\rightarrow\bar x$ ensures the linear convergences of $f(x^k)$ to $f(\bar x)$ and $\nabla f(x^k)$ to $0$ as $k\to\infty$. Moreover, the convergence rate $\norm{x^k-\bar x}=\mathcal{O}(m(k))$ with $m(k)\downarrow 0$ yields
$$
\abs{f(x^k)-f(\bar x)}=\mathcal{O}(m^2(k))\;\mbox{ and }\;\norm{\nabla f(x^k)}=\mathcal{O}(m(k))\;\mbox{ as }\;
k\to\infty. 
$$
\end{Proposition}

\begin{Proposition}\label{prop AIGD tech}
Let $\set{x^k}$ be a sequence generated by Algorithm~{\rm\ref{IGDm}} with 
\begin{align}\label{max Lt<1-nu}
\max\set{L\tau,2L\tau \bar \delta+(L\tau+1)\bar \beta^2}< 1-\nu
\end{align}
such that $x^k,x^k_{\rm in},x^k_{\rm ex}\in X$ for all $k=1,\ldots,K\in\N$. Consider the positive constants
\begin{align}\label{C1C2}
\alpha:&=\frac{(L \tau+1)\bar \beta^2+1-\nu }{4\tau},\nonumber\\
C_1:&=\frac{1-\nu-(L \tau+1)\bar \beta^2-2L\tau \bar \delta}{4\tau},\\
C_2:&=\sqrt{2}\max\set{\frac{\nu+1}{\tau },\frac{\bar\beta(L\tau+\nu+1)+L\tau\bar\delta}{\tau }}+4{\alpha}.\nonumber
\end{align}
Then we have the following estimates whenever $k=1,\ldots,K-1:$
\begin{align}
C_1\norm{z^{k+1}-z^k}^2&\le H_{\alpha}(z^k)-H_{\alpha}(z^{k+1}),\label{3.2(i)}\\
\norm{\nabla H_{\alpha}(z^{k})}&\le C_2\norm{z^{k+1}-z^k}\label{3.2(ii)}.
\end{align}
\end{Proposition}

\begin{proof}
By Lemma~\ref{lemma descent}, the Lipschitz continuity with constant $L>0$ of $\nabla f$ on $X $ yields
\begin{align*}
-\frac{L}{2}\norm{y-x}^2\le f(y)-f(x)-\dotproduct{\nabla f(x),y-x}\le \frac{L}{2}\norm{y-x}^2 \text{ for all }x,y\in X .
\end{align*}
For any $k=1,\ldots,K-1$, we use  the left-hand side inequality above with $y=x^k,x=x^k_{\rm in}$ and the right-hand side inequality with $y=x^{k+1},x=x^k_{\rm in}$ to get
\begin{align*}
 f(x^k)-f(x^k_{\rm in})-\dotproduct{\nabla f(x^k_{\rm in}),x^k-x^k_{\rm in}}&\ge -\frac{L }{2}\norm{x^k-x^k_{\rm in}}^2,
 \\
 f(x^{k+1})- f(x^k_{\rm in}) -\dotproduct{\nabla f(x^k_{\rm in}),x^{k+1}-x^k_{\rm in}}&\le \frac{L}{2}\norm{x^{k+1}-x^k_{\rm in}}^2.
\end{align*}
Subtracting the first inequality from the second one gives us 
\begin{align*}
f(x^{k+1})-f(x^k)-\dotproduct{\nabla f(x^k_{\rm in}),x^{k+1}-x^k}\le \frac{L}{2}\norm{x^{k+1}-x^k_{\rm in}}^2+\frac{L }{2}\norm{x^k-x^k_{\rm in}}^2,
\end{align*}
which can be rewritten in the form
\begin{align}\label{prop: 1 chain}
\begin{array}{ll}
\disp f(x^{k+1})-f(x^k)\le \frac{L}{2}\norm{x^{k+1}-x^k_{\rm in}}^2+\frac{L }{2}\norm{x^k-x^k_{\rm in}}^2+\dotproduct{\nabla f(x^k_{\rm in}),x^{k+1}-x^k}\\
=\disp\frac{L}{2} \norm{x^{k+1}-x^k_{\rm in}}^2+\frac{L \beta_k^2}{2}\norm{x^k-x^{k-1}}^2+\dotproduct{\nabla f(x^k_{\rm in})-\nabla f(x^k_{\rm ex}),x^{k+1}-x^k}\\
\disp+\dotproduct{\nabla f(x^k_{\rm ex})- g^k,x^{k+1}-x^k}+\dotproduct{g^k,x^{k+1}-x^k}.
\end{array}
\end{align}
By the Cauchy-Schwarz inequality, the Lipschitz continuity of $\nabla f$ on $X $, and the constructions of $x^k_{\rm in}$ and $x^k_{\rm ex}$ in \eqref{step xin} and \eqref{step xex}, we deduce the estimates
\begin{align}\label{prop: 1.1 chain}
\begin{array}{ll}
\dotproduct{\nabla f(x^k_{\rm in})-\nabla f(x^k_{\rm ex}),x^{k+1}-x^k}\le \norm{\nabla f(x^k_{\rm in})-\nabla f(x^k_{\rm ex})}\cdot\norm{x^{k+1}-x^k}\\
\le L\norm{x^k_{\rm in}-x^k_{\rm ex}}\cdot\norm{x^{k+1}-x^k}\le L\abs{\beta_k-\gamma_k}\norm{x^k-x^{k-1}}\cdot\norm{x^{k+1}-x^k}\\
\le\disp\frac{L\bar \delta}{2}\brac{\norm{x^k-x^{k-1}}^2+\norm{x^{k+1}-x^k}^2}.
\end{array}
\end{align}
It follows from the Cauchy-Schwarz and AM-GM inequalities together with the algorithm design $x^{k+1}:=x^k_{\rm in}-\tau  g^k$ and $\norm{g^k-\nabla f(x^k_{\rm ex})}\le \nu\norm{g^k}$ in \eqref{iteration update} that
\begin{align}\label{prop: 3 chain}
\begin{array}{ll}
\dotproduct{\nabla f(x^k_{\rm ex})- g^k,x^{k+1}-x^k}\le \norm{\nabla f(x^k_{\rm ex})- g^k}\cdot\norm{x^{k+1}-x^k}\\
\disp\le \nu \norm{g^k}\cdot\norm{x^{k+1}-x^k}=\frac{\nu}{\tau }\norm{x^k_{\rm in}-x^{k+1}}\cdot\norm{x^{k+1}-x^k}\\
\le\disp \frac{\nu}{2\tau }\brac{\norm{x^{k+1}-x^k_{\rm in}}^2+\norm{x^{k+1}-x^k}^2}.
\end{array}
\end{align}
Using further \eqref{step xin} and \eqref{iteration update},  we arrive at
\begin{align}\label{prop: 2 chain}
\begin{array}{ll}
\dotproduct{g^k,x^{k+1}-x^k}=\disp\frac{1}{\tau }\dotproduct{x^k_{\rm in}-x^{k+1},x^{k+1}-x^k}\\
=\disp\frac{1}{2\tau }\brac{\norm{x^k_{\rm in}-x^k}^2-\norm{x^{k+1}-x^k_{\rm in}}^2-\norm{x^k-x^{k+1}}^2}\\
=\disp\frac{1}{2\tau }\brac{\beta_k^2\norm{x^{k}-x^{k-1}}^2-\norm{x^{k+1}-x^k_{\rm in}}^2-\norm{x^k-x^{k+1}}^2}.
\end{array}
\end{align}
Combining \eqref{prop: 1 chain}--\eqref{prop: 2 chain} with taking into account $L\tau +\nu<1$ and $\beta_k\le \bar \beta$ gives us
\begin{align}\label{estimane conse}
\begin{array}{ll}
f(x^{k+1})-f(x^k)&\le\disp\frac{L\tau +\nu-1}{2\tau }\norm{x^{k+1}-x^k_{\rm in}}^2+\frac{L\tau\bar \delta+\nu-1}{2\tau }\norm{x^{k+1}-x^k}^2\\
&+\disp\frac{L \tau \beta_k^2+\beta_k^2+L\tau\bar \delta}{2\tau }\norm{x^k-x^{k-1}}^2\\
&\le\disp\frac{L\tau\bar \delta+\nu-1}{2\tau }\norm{x^{k+1}-x^k}^2+\frac{(L \tau +1)\bar \beta^2+L\tau\bar \delta}{2\tau }\norm{x^k-x^{k-1}}^2.
\end{array}
\end{align}
Since $\bar\beta^2<\frac{1-\nu}{L \tau+1}$, it follows that $\frac{(L \tau+1)\bar \beta^2+L\tau\bar \delta}{2\tau }<\frac{1-\nu-L\tau\bar \delta}{2\tau }$, and by $\alpha=\frac{(L \tau+1)\bar \beta^2+1-\nu}{4\tau}$ we get 
\begin{align*}
C_1=\frac{1-\nu-(L \tau+1)\bar \beta^2-2L\tau \bar \delta}{4\tau}=\frac{1-\nu-L\tau\bar\delta}{2\tau}-\alpha=\alpha-\frac{(L  \tau+1)\bar\beta^2+L\tau\bar \delta}{2\tau}
\end{align*}
for $C_1$ in \eqref{C1C2}. Using the latter together with \eqref{estimane conse} and the construction of $H_\alpha$ in \eqref{lyapunov func}  brings us to
\begin{align*}
H_{\alpha}(z^{k+1})-H_{\alpha}(z^k)&= f(x^{k+1})+\alpha\norm{x^{k+1}-x^k}^2-f(x^{k})-\alpha\norm{x^{k}-x^{k-1}}^2\\
&\le\brac{ \frac{\nu-1+L\tau\bar \delta}{2\tau }+\alpha}\norm{x^{k+1}-x^k}^2+\brac{\frac{(L \tau+1)\bar  \beta^2+L\tau\bar \delta}{2\tau }-\alpha}\norm{x^k-x^{k-1}}^2\\
&\le- C_1\brac{\norm{x^{k+1}-x^k}^2+\norm{x^k-x^{k-1}}^2}=-C_1\norm{z^{k+1}-z^k}^2,
\end{align*}
which therefore justifies the inequality in \eqref{3.2(i)}. 

To verify \eqref{3.2(ii)}, take any $k=1,\ldots,K-1$ and obtain the relationships
\begin{subequations}
\begin{align}
\norm{\nabla f(x^k)}&\le \norm{\nabla f(x^k)-\nabla f(x^k_{\rm in})} +\norm{\nabla f(x^k_{\rm in})-\nabla f(x^k_{\rm ex})}+\norm{\nabla f(x^k_{\rm ex})-g^k}+\norm{g^k}\label{nab.1 triang}\\
&\le(L\bar \beta+L\bar\delta)\norm{x^k-x^{k-1}}+(\nu+1)\norm{g^k}\label{nab.2}\\
&=(L\bar \beta+L\bar\delta)\norm{x^k-x^{k-1}}+\frac{\nu+1}{\tau }\norm{x^k+\beta_k(x^k-x^{k-1})-x^{k+1}}\label{nab.3}\\
&\le \brac{L\bar \beta+L\bar\delta+\frac{\nu+1}{\tau }\bar \beta}\norm{x^k-x^{k-1}}+\frac{\nu+1}{\tau }\norm{x^{k+1}-x^k}\nonumber\\
&\le \max\set{\frac{\nu+1}{\tau },L\bar \beta+L\bar\delta+\frac{\nu+1}{\tau }\bar \beta}\brac{\norm{x^{k+1}-x^k}+\norm{x^k-x^{k-1}}}\nonumber\\
&\le \sqrt{2}\max\set{\frac{\nu+1}{\tau },L\bar \beta+L\bar\delta+\frac{\nu+1}{\tau }\bar \beta}\norm{z^{k+1}-z^k}\label{nab.6},
\end{align}
\end{subequations}
where \eqref{nab.1 triang} follows from the triangle inequality; \eqref{nab.2} follows from $\norm{g^k-\nabla f(x^k_{\rm ex})}\le \nu\norm{g^k}$ in \eqref{iteration update}, the updates in \eqref{step xin}, \eqref{step xex}, and the Lipschitz continuity of $\nabla f$ on $X $ containing $ x^k_\rin,x^k_\rex$; \eqref{nab.3} follows from \eqref{step xin} and \eqref{step xex}; \eqref{nab.6} follows from $a+b\le \sqrt{2(a^2+b^2)}$ and $z^k=(x^k,x^{k-1})$. By using the estimates above, we deduce from the construction of $H_\alpha$ and inequality $\sqrt{a^2+b^2}\le a+b$ for $a,b\ge 0$ that
\begin{align*}
\norm{\nabla H_{\alpha}(z^k)}&= \sqrt{\norm{\nabla f(x^k)+2{\alpha}(x^k-x^{k-1})}^2+\norm{2{\alpha} (x^k-x^{k-1})}^2}\\
&\le \norm{\nabla f(x^k)+2{\alpha}(x^k-x^{k-1})}+\norm{2{\alpha} (x^k-x^{k-1})}\\
& \le \norm{\nabla f(x^k)}+4{\alpha}\norm{x^k-x^{k-1}}\\
&\le \brac{\sqrt{2}\max\set{\frac{\nu+1}{\tau },L\bar \beta+L\bar\delta+\frac{\nu+1}{\tau }\bar \beta}+4{\alpha}}\norm{z^{k+1}-z^k},
\end{align*}
which justifies \eqref{3.2(ii)}  and thus completes the proof of the proposition.
\end{proof}

\begin{Proposition}\label{proposition distance}
Let $\set{x^k}$ be the sequence of iterates generated by Algorithm~{\rm\ref{IGDm}} such that $x^k,x^k_{\rm ex}\in \B(\bar x,\rho)\subset X$ for all $k=1,\ldots,K$. Then we have for all $k=1,\ldots,K$ that
\begin{align}
\norm{x^{k+1}-x^k}&\le   \frac{L\tau\rho }{(1-\bar \beta)(1-\nu)},\label{3.3(i)}\\
\norm{z^{k+1}-z^k}&\le  \frac{\sqrt{2} L\tau\rho }{(1-\bar \beta)(1-\nu)}.\label{3.3(ii)}
\end{align}
\end{Proposition}

\begin{proof}
Pick any $k=1,\ldots,K$ and observe that the iteration update in Algorithm~\ref{IGDm} can be rewritten as $x^{i+1}=x^i+\beta_k(x^i-x^{i-1})-\tau g^i$, which yields
\begin{align}\label{new update}
\norm{x^{i+1}-x^i}\le \bar \beta \norm{x^i-x^{i-1}}+\tau\norm{g^i}\;\text{ for all }\;i\le k.
\end{align}
Using the triangle inequality together with $\norm{g^i-\nabla f(x^i_{\rm ex})}\le \nu \norm{g^k}$ gives us
\begin{align*}
\norm{\nabla f(x^i_{\rm ex})}\ge \norm{g^i}-\norm{\nabla f(x^i_{\rm ex})-g^i}\ge (1-\nu)\norm{g^i}\;\text{ for all }\;i\le k.
\end{align*} 
Proceeding inductively from \eqref{new update} for $i=k,k-1,\ldots,1$ with the usage of the Lipschitz continuity of $\nabla f$ on the ball $\B(\bar x,\rho)$ containing $\bar x$ and $x^{k-i}_\rex,i=0,\ldots,k-1$ yields
\begin{align*}
\norm{x^{k+1}-x^k}&\le \bar \beta\norm{x^k-x^{k-1}}+\tau \norm{g^k}\\
&=\bar \beta^2\norm{x^{k-1}-x^{k-2}}+\tau\brac{\bar \beta \norm{g^{k-1}}+\norm{g^k}}\\
&\ldots\\
&\le\bar \beta^{k}\norm{x^1-x^0}+\tau \sum_{i=0}^{k-1}\bar \beta^i\norm{g^{k-i}}\\
&\le \frac{\tau}{1-\nu} \sum_{i=0}^{k-1}\bar \beta^i\norm{\nabla f(x_\rex^{k-i})} = \frac{\tau}{1-\nu}\sum_{i=0}^{k-1}\bar \beta^i\norm{\nabla f(x^{k-i}_\rex)-\nabla f(\bar x)}\\
&\le \frac{\tau}{1-\nu}\sum_{i=0}^{k-1}\bar \beta^i L\norm{x^{k-i}_\rex -\bar x}\le \frac{\tau}{1-\nu}\sum_{i=0}^{k-1}\bar \beta^i L\rho\\
&\le \frac{L\tau\rho}{1-\nu}\sum_{i=0}^{\infty}\bar \beta^i = \frac{L\tau\rho}{(1-\nu)(1-\bar \beta)},
\end{align*}
where the latter inequality follows from $\bar \beta\in [0,1)$. This readily verifies \eqref{3.3(i)}. Combining \eqref{3.3(i)}  with $\norm{z^{k+1}-z^k}=\sqrt{\norm{x^{k+1}-x^k}^2+\norm{x^{k}-x^{k-1}}^2}$ brings us to \eqref{3.3(ii)} and thus completes the proof.
\end{proof}

\begin{Proposition}\label{convergence xk+1 xk} Let $\set{x^k}$ be the sequence of iterates generated by Algorithm~{\rm\ref{IGDm}} that converges to some $\tilde x\in X$. Then $\tilde x$ is a stationary point of \eqref{main problem} and the sequences $\set{x^k_\rex},\set{x^k_\rin}$ converge to $\tilde x$ as well.
\end{Proposition}

\begin{proof} Since the sequence $\set{x^k}$ is convergent,  we have $\norm{x^{k+1}-x^k}\rightarrow 0$ as $k\rightarrow\infty.$ Combining this with the updates in \eqref{step xin} and \eqref{step xex} together with the boundedness of $\set{\beta_k} and \set{\gamma_k}$ tells us that
\begin{align*}
{x^k_{\rm in}}&=x^k+\beta_k({x^{k}-x^{k-1}})\rightarrow\tilde x,\\
{x^k_{\rm ex}}&=x^k+\gamma_k({x^{k}-x^{k-1}})\rightarrow\tilde x.
\end{align*}
Using $\norm{x^{k+1}-x^k}\rightarrow 0$ and the updates in \eqref{step xin}, \eqref{iteration update} of Algorithm~\ref{IGDm} yields
\begin{align*}
g^k=\frac{1}{\tau}\brac{x^k-x^{k+1}+\beta_k(x^k-x^{k-1})}\rightarrow 0\;\text{ as }\;k\rightarrow\infty.
\end{align*}
It follows from $\norm{\nabla f(x^k_{\rm ex})-g^k}\le \nu\norm{g^k}$ in \eqref{iteration update} that ${\nabla f(x^k_{\rm ex})}\rightarrow 0$, and we are done with the proof.
\end{proof}

\begin{proof} To verify (i), deduce from $\bar \beta \in[0,\sqrt{1-\nu})$ that there exists $T>0$ such that
\begin{align}\label{LT<1}
T< \frac{(1-\bar \beta)(1-\nu)}{4L\sqrt{2}(1+\bar \delta)},\quad(LT+1)\bar\beta^2+2LT\bar \delta<1-\nu,\quad LT\le 1-\nu.
\end{align}
Define further $\varepsilon:=\min\set{\frac{1-\nu}{4T},\frac{1}{4}}\in \big(0,\frac{1}{4}\big]$ and deduce from Lemma~\ref{isolation lemma} due to the imposed assumptions that there exists a neighborhood $U\subset\B(\bar x,r)$ of $\bar x$ such that $\bar x$ minimizes $f$ on $U$ and that $f(\bar x)$ is the only critical value within this set. Remembering that $f$ satisfies the basic PLK condition at $\bar x$ tells us by Proposition~\ref{isolated} that the Lyapunov function $\set{H_\alpha}_{\alpha\ge \varepsilon}$ enjoys the same PLK property at $\bar z:=(\bar x,\bar x)$ for some $\eta\in (0,\infty]$, some neighborhood $Z$ of $\bar z:=(\bar x,\bar x)$, and a concave desingularizing function $\varphi:[0,\eta)\rightarrow[0,\infty)$ with $\varphi(0)=0$ which is ${\cal C}^1$-smooth on $(0,\eta)$. This means that for any $\alpha\ge \varepsilon$ and any $z\in Z$ with $H_\alpha(\bar z)< H_\alpha( z)<H_\alpha(\bar z)+\eta$, we get the inequality
\begin{align}\label{KL R2n in proof}
\varphi'\big(H_\alpha(z )-H_\alpha(\bar z )\big)\norm{\nabla H_\alpha(z)}\ge 1.
\end{align}
The continuity of $f$ allows us to find $\rho\in(0,r)$ such that 
\begin{align}\label{choice rho}
f(x)+\frac{L^2T\rho^2}{2(1-\bar \beta)^2(1-\nu)^2}< f(\bar x)+\eta\text{ for all }x \in \mathbb{B}(\bar x,\rho).
\end{align}
Invoking further the continuity of $\varphi$ at $0$ with $\varphi(0)=0$ gives us $\xi\in (0,\rho]$ for which
\begin{align}\label{defi xi 1}
\sqrt{2}\norm{x-\bar x}+\frac{4\sqrt{2}\max\set{\nu+1,\bar\beta(\nu+2)+\bar\delta}+8}{1-\nu-(L  T+1)\bar\beta^2-2LT \bar \delta}\varphi(f(x)-f(\bar x))&<\frac{\rho}{4}\;\text{ for all }\;x\in\mathbb{B}(\bar x,\xi).
\end{align}
Given the sequence of iterates $\set{x^k}$ generated by Algorithm~\ref{IGDm} with $x^0\in \mathbb{B}(\bar x, \xi)$ and $\tau\in (0, T]$, take the constant $\alpha,C_1,C_2$ from \eqref{C1C2} and deduce that
\begin{align}\label{sele alpha}
\alpha=\frac{(L\tau+1)\bar\beta^2+1-\nu}{4\tau}\ge \frac{1-\nu}{4T}\ge \varepsilon.
\end{align}
Since $\tau\le T$, we get from the selection of $T$ in \eqref{LT<1} the inequalities
\begin{align}\label{ineq 1-nu}
(L\tau+1)\bar \beta^2+2L\tau \bar \delta\le (LT+1)\bar \beta^2+2LT \bar \delta <1-\nu.
\end{align}
which bring us to the relationships  
\begin{align}\label{ineq 1/2}
\alpha=\frac{(L\tau+1)\bar\beta^2+1-\nu}{4\tau}\le \frac{2(1-\nu)-2L\tau \bar \delta}{4\tau}=\frac{1-\nu-L\tau \bar \delta}{2\tau}\le \frac{1}{2\tau}.
\end{align} 
It follows from $L\tau \le LT\le 1$ by \eqref{LT<1} and the estimates in \eqref{ineq 1/2}, \eqref{ineq 1-nu} that
\begin{align*}
\frac{C_2}{C_1}&= \frac{\sqrt{2}\max\set{\frac{\nu+1}{\tau },\frac{\bar\beta(L\tau+\nu+1)+L\tau \bar \delta}{\tau }}+4\alpha}{\frac{1-\nu-(L \tau+1)\bar \beta^2-2L\tau \bar \delta}{4\tau}}\\
&= \frac{4\sqrt{2}\max\set{{\nu+1}, \bar\beta(L\tau+\nu+1)+L\tau \bar \delta}+16\alpha\tau}{1-\nu-(L \tau+1)\bar\beta^2-2L\tau \bar \delta}\\
&\le \frac{4\sqrt{2}\max\set{\nu+1,\bar\beta(\nu+2)+\bar\delta}+8}{1-\nu-(L  T+1)\bar\beta^2-2LT \bar \delta}.
\end{align*}
This implies by \eqref{defi xi 1} that 
\begin{align}\label{defi xi 2}
\sqrt{2}\norm{x-\bar x}+\frac{C_2}{C_1}\varphi(f(x)-f(\bar x))&<\frac{\rho}{4} \text{ for all }x\in\mathbb{B}(\bar x,\xi).
\end{align}
The rest of the proof of assertion (i) is split into two claims.

\begin{Claim} The sequences $\set{x^k},\set{x^k_{\rm in}}$, and $\set{x^k_{\rm ex}}$ stay inside $\mathbb{B}(\bar x,\rho)$ for all $k\in\N$.
\end{Claim}
\noindent Since $x^0=x^1\in \mathbb{B}(\bar x,\xi),$ the updates in \eqref{step xin}, \eqref{step xex} of Algorithm~\ref{IGDm} tell us that $x^1_{\rm in}=x^1_{\rm ex}=x^1\in \mathbb{B}(\bar x,\xi)\subset \mathbb{B}(\bar x,\rho).$ We proceed now by induction to show that $x^k,x^k_{\rm in},x^k_{\rm ex}\in \mathbb{B}(\bar x,\rho)$ for all $k\in\N.$ Assuming that $x^k,x^k_\rin,x^k_{\rm ex}\in \mathbb{B}(\bar x,\rho)$ for $k=1,\ldots,K$, let us verify that $x^{K+1},x_\rin^{K+1},x^{K+1}_\rex\in \mathbb{B}(\bar x,\rho).$ It follows from \eqref{ineq 1-nu} and $L\tau\le LT<1-\nu$ by \eqref{LT<1} that assumption \eqref{max Lt<1-nu} in Proposition~\ref{prop AIGD tech} is satisfied. Therefore, we get the estimates
\begin{align}\label{descent con for rate 1}
&C_1 \norm{z^{k+1}-z^k}^2\le H_{\alpha}(z^k)-H_{\alpha}(z^{k+1}),\\
&\norm{\nabla H_{\alpha}(z^{k})}\le C_2\norm{z^{k+1}-z^k}\text{ for all }k=1,\ldots,K-1,\label{descent con for rate 2}
\end{align}
where $z^k=(x^k,x^{k-1})$ as before. Fix any such $k,$ we deduce from the above inequalities that
\begin{align}\label{primary descent condi}
\norm{z^{k+1}-z^k}\cdot\norm{\nabla H_\alpha(z^k)}\le C_2  \norm{z^{k+1}-z^k}^2\le \frac{C_2}{C_1}(H_\alpha(z^k)-H_\alpha(z^{k+1})).
\end{align}
To use inequality \eqref{KL R2n in proof} with $z:=z^k$, it is sufficient to check that $z^k\in Z$ and $ H_\alpha(\bar z)<H_\alpha(z^k)<H_\alpha(\bar z)+\eta$. Note first that the former condition is satisfied due to
\begin{align*}
z^k=(x^k,x^{k-1})\in \mathbb{B}(\bar x,\rho)\times \mathbb{B}(\bar x,\rho)\subset Z.
\end{align*}
 To verify the latter condition, deduce from Proposition~\ref{proposition distance} that $\norm{x^k-x^{k-1}}\le \frac{L\tau\rho}{(1-\bar \beta)(1-\nu)}$. Combining this with the construction of $H_\alpha$, the inequality $\alpha\le \frac{1}{2\tau}$ from \eqref{ineq 1/2}, the algorithm inclusions $x^k,x^{k-1}\in\mathbb{B}(\bar x,\rho)$, and the choice of $\rho$ in \eqref{choice rho} tells us that
\begin{align*}
H_\alpha(z^k)&=f(x^k)+\alpha\norm{x^k-x^{k-1}}^2\\
&\le f(x^k)+\frac{1}{2\tau}\cdot\frac{L^2\tau^2\rho^2}{(1-\bar \beta)^2(1-\nu)^2}\\
&= f(x^k)+\frac{L^2T\rho^2}{2(1-\bar \beta)^2(1-\nu)^2}< f(\bar x)+\eta=H_\alpha(\bar z)+\eta.
\end{align*}
Observe that the inequality $H_\alpha(\bar z)<H_\alpha(z^k)$ is also satisfied. Indeed, its failure means that 
$$
f(x^k)+\alpha\norm{x^{k}-x^{k-1}}^2\le H_\alpha(\bar z)=f(\bar x).
$$
By taking into account that $f(x^k)\ge f(\bar x)$ by $x^k\in\mathbb{B}(\bar x,\rho)$, the latter implies that
\begin{align*}
f(x^k)=f(\bar x) \text{ and }x^{k}=x^{k-1},
\end{align*}
which  means that $\nabla f(x^k)=0$ since $\bar x$ is a local minimizer of $f$ within $\B(\bar x,\rho)$. The equalities above also imply that
$x^k_{\rm ex}=x^k$ by \eqref{step xex}, and so $\nabla f(x^k_{\rm ex})=0,$ which contradicts Assumption~\ref{assu} and thus justifies \eqref{KL R2n in proof} with $z=z^k$. Multiplying both sides of \eqref{primary descent condi} by $\varphi'(H_\alpha(z^k)-H_\alpha(\bar z))$ and using \eqref{KL R2n in proof} give us
\begin{align}\label{ineq alter}
\norm{z^{k+1}-z^k}& \le \varphi'(H_\alpha(z^k)-H_\alpha(\bar z))\norm{\nabla H_\alpha(z^k)}\cdot\norm{z^{k+1}-z^k}\\
&\le \frac{C_2}{C_1}\varphi'(H_\alpha(z^k)-H_\alpha(\bar z))\brac{ H_{\alpha}(z^k)-H_{\alpha}(z^{k+1})}\nonumber\\
&\le\frac{C_2}{C_1}\brac{\varphi(H_\alpha(z^k)-H_\alpha(\bar z))-\varphi(H_\alpha(z^{k+1})-H_\alpha(\bar z))} \text{ for all }k=1,\ldots,K-1,
\end{align}
where the inequality  in \eqref{chain ineq} follows from the concavity of $\varphi.$
Combining further the obtained estimate with $\tau\le T<\frac{(1-\bar \beta)(1-\nu)}{4L\sqrt{2}}$ from \eqref{LT<1} and estimate \eqref{3.3(ii)} from Proposition~\ref{proposition distance},  we have
\begin{align}
\norm{z^{K+1}-\bar z}&\le\norm{z^1-\bar z}+\norm{z^{K+1}-z^K}+\sum_{k=1}^{K-1}\norm{z^{k+1}-z^k}\nonumber\\
&\le \norm{z^1-\bar z}+\norm{z^{K+1}-z^K}+\frac{C_2}{C_1}\sum_{k=1}^{K-1}\brac{\varphi(H_\alpha(z^k)-H_\alpha(\bar z))-\varphi(H_\alpha(z^{k+1})-H_\alpha(\bar z))}\nonumber\\
&=\sqrt{2}\norm{x^1-\bar x}+\frac{\sqrt{2}L\rho\tau}{(1-\bar \beta)(1-\nu)}+\frac{C_2}{C_1}\brac{\varphi(H_\alpha(z^1)-H_\alpha(\bar z))-\varphi(H_\alpha(z^{K})-H_\alpha(\bar z))}\nonumber\\
&\le \sqrt{2}\norm{x^1-\bar x}+\frac{\rho}{4}+\frac{C_2}{C_1}\varphi(f(x^1)-f(\bar x))<\rho/2,\label{chain ineq}
\end{align}
where the last inequality is a consequence of \eqref{defi xi 2} and $x^1\in\B(\bar x,\xi)$. 
Therefore, 
\begin{align*}
\norm{x^{K+1}-\bar x}\le \norm{z^{K+1}-\bar z}\le \rho/2,
\end{align*}
which means that $x^{K+1}\in\mathbb{B}(\bar x,\rho/2)$. Using the updates in \eqref{step xin} and \eqref{step xex} at the $(K+1)^{\rm th}$ iteration with taking into account \eqref{3.3(ii)} from Proposition~\ref{proposition distance}, $\tau\le T<\frac{(1-\bar \beta)(1-\nu)}{4L\sqrt{2}(1+\bar\delta)}$ from \eqref{LT<1}, and  
\begin{align*}
0\le \beta_{K+1}<1,\quad 0\le \delta_{K+1}\le \delta_{K+1}-\beta_{K+1}+\beta_{K+1}\le \bar \delta +1,
\end{align*}
we arrive at the estimates
\begin{align*}
\norm{x^{K+1}_\rin-\bar x}&\le \norm{x^{K+1}-\bar x}+\norm{x^{K+1}-x^K}\le \rho/2+ \frac{2L\tau\rho}{(1-\bar \beta)(1-\nu)}<\rho,\\
\norm{x^{K+1}_\rex-\bar x}&\le \norm{x^{K+1}-\bar x}+(1+\bar \delta)\norm{x^{K+1}-x^K}\le \rho/2+ \frac{2L\tau\rho(1+\bar\delta)}{(1-\bar \beta)(1-\nu)}<\rho.
\end{align*}
Thus $x^{K+1}_\rin,x^{K+1}_\rex\in\mathbb{B}(\bar x,\rho)$, which completes the claimed assertion by induction. 
\medskip

\noindent\textbf{Claim~2.} \textit{The sequences $\set{x^k},\set{x^k_{\rm in}},\set{x^k_{\rm ex}}$ converge to a local minimizer $\tilde x$ of $f$ with $f(\tilde x)=f(\bar x)$.}
\medskip

\noindent Indeed, it follows from \eqref{ineq alter} and $x^k,x^k_\rin,x^k_{\rm ex}\in\mathbb{B}(\bar x,\rho)$ from Claim 1 that 
\begin{align*}
\norm{z^{k+1}-z^k}&\le \frac{C_2}{C_1}\brac{\varphi(H_\alpha(z^k)-H_\alpha(\bar z))-\varphi(H_\alpha(z^{k+1})-H_\alpha(\bar z))} \text{ for all }k\in\N.
\end{align*}
This readily implies that 
\begin{align*}
\sum_{k=1}^\infty \norm{z^{k+1}-z^k}\le \frac{C_2}{C_1}\varphi(H_\alpha(z^1)-H_\alpha(\bar z))<\infty.
\end{align*}
Therefore, $\set{z^k}$ is convergent, and thus $\set{x^k}$ converges to some $\tilde x\in\overline{\mathbb{B}}(\bar x,\rho)\subset U$. Using  Proposition~\ref{convergence xk+1 xk}, we justify the convergence of $\set{x^k_\rex},\set{x^k_\rin}$ to $\tilde x$ and that $\tilde x$ is a stationary point of $f.$ Since $f(\bar x)$ is the only critical value of $f$ within $U,$ it gives us $f(\tilde x)=f(\bar x)$ and shows that $\tilde x$ is a local minimizer of $f$.\vspace*{0.05in} 

To verify (ii), we employ Proposition~\ref{general rate}. Letting $\tilde z:=(\tilde x,\tilde x)$ and using \eqref{descent con for rate 1}, \eqref{descent con for rate 2} from the proof of Claim~1 in (i) together with $\set{x^k},\set{x^k_{\rm in}},\set{x^k_{\rm ex}}\subset\mathbb{B}(\bar x,\rho)$ give us the estimate
\begin{align}\label{ineq rate grad}
\begin{array}{ll}
C_1 \norm{z^{k+1}-z^k}^2\le H_{\alpha}(z^k)-H_{\alpha}(z^{k+1}),\\
\norm{\nabla H_{\alpha}(z^{k})}\le C_2\norm{z^{k+1}-z^k},\quad k\in\N.
\end{array}
\end{align}
Observe from $\nabla f(x^k_\rex)\ne 0$ and $\norm{g^k-\nabla f(x^k_\rex)}\le \nu \norm{g^k}$ that $z^{k+1}\ne z^k$ for all $k\in\N.$ Indeed, the contrary implies by $z^k=(x^{k},x^{k-1})$ that $x^{k+1}=x^k=x^{k-1}$ for some $k\in\N$. Using the updates in \eqref{step xin}, \eqref{step xex} of Algorithm~\ref{IGDm} ensures that $x^k_{\rm ex}=x^k_{\rm in}=x^k=x^{k+1}$. Then $g^k=0$ by \eqref{iteration update}, and hence $\nabla f(x^k_{\rm ex})=0$ by $\norm{g^k-\nabla f(x^k_\rex)}\le \nu \norm{g^k}$. This contradicts the assumption $\nabla f(x^k_{\rm ex})\ne 0$ for all $k\in\N$.

Recalling that $f$ satisfies the PLK condition at $\bar x$ with the desingularizing function $\psi(t)=Mt^{1-q}$, we deduce from Proposition~\ref{isolated}(ii) that $H_\alpha$ satisfies the PLK condition at $(\bar x,\bar x)$ with the neighborhood $Z$ taking from \eqref{KL R2n in proof} and the desingularizing function $\varphi(t)=\overline Mt^{1-\theta}$, where $\theta=\max \set{q,\frac{1}{2}}\in (0,1),\overline{M}>0.$ Taking into account Remark~\ref{algebraic}, this PLK property also holds at $\tilde z\in\overline{\mathbb{B}}(\bar x,\rho)\times \overline{\mathbb{B}}(\bar x,\rho)\subset Z$ due to $H_\alpha(\tilde z)=f(\tilde x)=f(\bar x)=H_\alpha(\bar z).$  Then Proposition~\ref{general rate} applied to the function $H_\alpha$ and sequence $\set{z^k}\subset\R^{n}\times \R^n$, with taking into account Remark~\ref{rmk general rate}, brings us to the following:
\begin{itemize}
\item For $q\in[0,1/2],$ we get $\theta=1/2$, which ensures that $\set{z^k}$ converges linearly to $(\tilde x,\tilde x)$. This implies that $\set{x^k}$ converges linearly to $\tilde x.$

\item For $q\in (1/2,1),$ we get $\theta=q\in (1/2,1)$, which tells us that $\norm{z^k-(\tilde x,\tilde x)}=\mathcal{O}(k^{-\frac{1-q}{2q-1}})$ and thus yields the convergence rate $\norm{x^k-\tilde x}=\mathcal{O}(k^{-\frac{1-q}{2q-1}})$ as $k\rightarrow\infty$.
\end{itemize}

Finally, we employ Proposition~\ref{convergence rate deduce} to verify the convergence rates of $\set{\nabla f(x^k)}$ and $\set{f(x^k)}.$ Since $f$ is of class ${\cal C}^{1,1}$ on $\B(\bar x,r)$ and since $H_\alpha$ is of class ${\cal C}^{1,1}$ on $\B(\bar x,r)\times \B(\bar x,r)\supset \set{z^k}$, condition \eqref{main condition rate} follows from \eqref{ineq rate grad}. This clearly leads us to the conclusions:
\begin{itemize}
\item For $q\in[0,1/2),$ we get $\theta=1/2$. Therefore, $\{H_\alpha(z^k)\}$ converges linearly to $H_\alpha(\bar z)$ and $\{\norm{\nabla H_\alpha(z^k)}\}$ converges linearly to $0$ as $k\to\infty$.

\item For $q\in (1/2,1),$ we have $H_\alpha(z^k)-H_\alpha(\tilde z)=\mathcal{O}(k^{-\frac{2-2q}{2q-1}})$ and $\norm{\nabla H_\alpha(z^k)}=\mathcal{O}(k^{-\frac{1-q}{2q-1}})$ as $k\to\infty$.
\end{itemize}
The claimed convergence rates of the sequences $\{\norm{\nabla f(x^k)}\}$ and $\set{f(x^k)}$ are now deduced from those for $\set{\norm{\nabla H_\alpha (z^k)}},\set{H_\alpha (z^k)}$ and the estimates
\begin{align*}
\norm{\nabla H_\alpha(x,y)}&=\sqrt{\norm{\nabla f(x)+2\alpha (x-y)}^2+4\alpha^2\norm{x-y}^2}\ge \norm{\nabla f(x)},\\
H_\alpha(x,y)&=f(x)+\alpha\norm{x-y}^2\ge f(x)\;\text{ for all }\;x,y\in\R^n.
\end{align*}
This completes the proof of the theorem.
\end{proof}

