\begin{proof} To verify (i), deduce from $\bar \beta \in[0,\sqrt{1-\nu})$ that there exists $T>0$ such that
\begin{align}\label{LT<1}
T< \frac{(1-\bar \beta)(1-\nu)}{4L\sqrt{2}(1+\bar \delta)},\quad(LT+1)\bar\beta^2+2LT\bar \delta<1-\nu,\quad LT\le 1-\nu.
\end{align}

Define further $\varepsilon:=\min\set{\frac{1-\nu}{4T},\frac{1}{4}}\in \big(0,\frac{1}{4}\big]$ and deduce from Lemma~\ref{isolation lemma} due to the imposed assumptions that there exists a neighborhood $U\subset\B(\bar x,r)$ of $\bar x$ such that $\bar x$ minimizes $f$ on $U$ and that $f(\bar x)$ is the only critical value within this set. Remembering that $f$ satisfies the basic PLK condition at $\bar x$ tells us by Proposition~\ref{isolated} that the Lyapunov function $\set{H_\alpha}_{\alpha\ge \varepsilon}$ enjoys the same PLK property at $\bar z:=(\bar x,\bar x)$ for some $\eta\in (0,\infty]$, some neighborhood $Z$ of $\bar z:=(\bar x,\bar x)$, and a concave desingularizing function $\varphi:[0,\eta)\rightarrow[0,\infty)$ with $\varphi(0)=0$ which is ${\cal C}^1$-smooth on $(0,\eta)$. This means that for any $\alpha\ge \varepsilon$ and any $z\in Z$ with $H_\alpha(\bar z)< H_\alpha( z)<H_\alpha(\bar z)+\eta$, we get the inequality
\begin{align}\label{KL R2n in proof}
\varphi'\big(H_\alpha(z )-H_\alpha(\bar z )\big)\norm{\nabla H_\alpha(z)}\ge 1.
\end{align}

The continuity of $f$ allows us to find $\rho\in(0,r)$ such that 
\begin{align}\label{choice rho}
f(x)+\frac{L^2T\rho^2}{2(1-\bar \beta)^2(1-\nu)^2}< f(\bar x)+\eta\text{ for all }x \in \mathbb{B}(\bar x,\rho).
\end{align}
Invoking further the continuity of $\varphi$ at $0$ with $\varphi(0)=0$ gives us $\xi\in (0,\rho]$ for which
\begin{align}\label{defi xi 1}
\sqrt{2}\norm{x-\bar x}+\frac{4\sqrt{2}\max\set{\nu+1,\bar\beta(\nu+2)+\bar\delta}+8}{1-\nu-(L  T+1)\bar\beta^2-2LT \bar \delta}\varphi(f(x)-f(\bar x))&<\frac{\rho}{4}\;\text{ for all }\;x\in\mathbb{B}(\bar x,\xi).
\end{align}

Given the sequence of iterates $\set{x^k}$ generated by Algorithm~\ref{IGDm} with $x^0\in \mathbb{B}(\bar x, \xi)$ and $\tau\in (0, T]$, take the constant $\alpha,C_1,C_2$ from \eqref{C1C2} and deduce that
\begin{align}\label{sele alpha}
\alpha=\frac{(L\tau+1)\bar\beta^2+1-\nu}{4\tau}\ge \frac{1-\nu}{4T}\ge \varepsilon.
\end{align}
Since $\tau\le T$, we get from the selection of $T$ in \eqref{LT<1} the inequalities
\begin{align}\label{ineq 1-nu}
(L\tau+1)\bar \beta^2+2L\tau \bar \delta\le (LT+1)\bar \beta^2+2LT \bar \delta <1-\nu.
\end{align}
which bring us to the relationships  
\begin{align}\label{ineq 1/2}
\alpha=\frac{(L\tau+1)\bar\beta^2+1-\nu}{4\tau}\le \frac{2(1-\nu)-2L\tau \bar \delta}{4\tau}=\frac{1-\nu-L\tau \bar \delta}{2\tau}\le \frac{1}{2\tau}.
\end{align}

It follows from $L\tau \le LT\le 1$ by \eqref{LT<1} and the estimates in \eqref{ineq 1/2}, \eqref{ineq 1-nu} that
\begin{align*}
\frac{C_2}{C_1}&= \frac{\sqrt{2}\max\set{\frac{\nu+1}{\tau },\frac{\bar\beta(L\tau+\nu+1)+L\tau \bar \delta}{\tau }}+4\alpha}{\frac{1-\nu-(L \tau+1)\bar \beta^2-2L\tau \bar \delta}{4\tau}}\\
&= \frac{4\sqrt{2}\max\set{{\nu+1}, \bar\beta(L\tau+\nu+1)+L\tau \bar \delta}+16\alpha\tau}{1-\nu-(L \tau+1)\bar\beta^2-2L\tau \bar \delta}\\
&\le \frac{4\sqrt{2}\max\set{\nu+1,\bar\beta(\nu+2)+\bar\delta}+8}{1-\nu-(L  T+1)\bar\beta^2-2LT \bar \delta}.
\end{align*}
This implies by \eqref{defi xi 1} that 
\begin{align}\label{defi xi 2}
\sqrt{2}\norm{x-\bar x}+\frac{C_2}{C_1}\varphi(f(x)-f(\bar x))&<\frac{\rho}{4} \text{ for all }x\in\mathbb{B}(\bar x,\xi).
\end{align}

